ValidationRule.errorConditionFormula:
AND(
    OR(RecordType.DeveloperName = "NewOperationalTest", RecordType.DeveloperName = "OldNewOperationalTest"),
    OR(
        AND(
            ISPICKVAL(StageName__c, "フェーズ9 役員内定"),
            OR(
                NOT(INCLUDES(CompletionBasis__c, "9-1:担当役員に内諾をいただいた。")),
                NOT(INCLUDES(CompletionBasis__c, "9-2:その後の工程、進め方について、担当者と打ち合わせを行った。")),
                NOT(INCLUDES(CompletionBasis__c, "9-3:現場運用に関する打ち合わせを行うための、日程調整が完了した。"))
            )
        )
    )
)
